// Generated from n8n/src/*.js by scripts/build-workflows.mjs. Edit the source files, not this node.

const DEFAULT_TIMEZONE = "Asia/Kolkata";

/** Calendar date ("YYYY-MM-DD") of an instant, in the given timezone. */
function isoDateInTimezone(ms, timezone) {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: timezone || DEFAULT_TIMEZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(new Date(ms));
  const get = (type) => parts.find((p) => p.type === type).value;
  return `${get("year")}-${get("month")}-${get("day")}`;
}

/**
 * Accepts what Bubble can send for a date: a UNIX timestamp in ms (or s),
 * a "YYYY-MM-DD" string, or any ISO timestamp. Empty values mean "no date".
 * Returns "YYYY-MM-DD", null for empty, or undefined if unparseable.
 */
function parseCalendarDate(value, timezone) {
  if (value === null || value === undefined) return null;
  const raw = String(value).trim();
  if (raw === "" || raw === "null" || raw === "undefined") return null;
  if (/^-?\d+(\.\d+)?$/.test(raw)) {
    let ms = Number(raw);
    if (Math.abs(ms) < 1e11) ms *= 1000; // seconds, not milliseconds
    return isoDateInTimezone(ms, timezone);
  }
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return isValidIsoDate(raw) ? raw : undefined;
  const ms = Date.parse(raw);
  if (Number.isNaN(ms)) return undefined;
  return isoDateInTimezone(ms, timezone);
}

function isValidIsoDate(iso) {
  const d = new Date(`${iso}T00:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === iso;
}

/** Parses "1,234", "₹1,234", 1234 → 1234. Returns NaN for anything else. */
function parseAmount(value) {
  if (typeof value === "number") return value;
  if (value === null || value === undefined) return NaN;
  const cleaned = String(value).replace(/[₹,\s]|INR|Rs\.?/gi, "");
  if (cleaned === "") return NaN;
  return /^-?\d+(\.\d+)?$/.test(cleaned) ? Number(cleaned) : NaN;
}

function parseYesNo(value) {
  if (typeof value === "boolean") return value;
  const raw = String(value ?? "").trim().toLowerCase();
  if (["yes", "true", "1", "y"].includes(raw)) return true;
  if (["no", "false", "0", "n", ""].includes(raw)) return false;
  return undefined;
}

/**
 * Every answer n8n gives Bubble has the same keys, whatever the outcome, so
 * Bubble's API Connector can be initialised once and every field mapped into
 * the Notification Log. Empty strings / zeros mean "not applicable".
 */
const RESPONSE_TEMPLATE = {
  status: "", // "Success" | "Failed" | "Duplicate"
  notification_id: "",
  author_id: "",
  completed_at: "", // ISO-8601 timestamp of when n8n finished
  email_subject: "",
  email_html: "",
  email_text: "",
  email_delivery: "not_attempted", // "sent" | "disabled" | "failed" | "not_attempted"
  intended_recipient: "",
  delivered_to: "",
  ai_model: "",
  ai_attempts: 0,
  prompt_version: "",
  total_earned: 0,
  total_paid: 0,
  total_pending: 0,
  overdue_books: 0,
  escalated_to_finance: "no",
  duplicate_of: "",
  error_code: "",
  error_message: "",
  n8n_execution_id: "",
  duration_ms: 0,
};

function buildResponse(fields, nowMs) {
  const response = { ...RESPONSE_TEMPLATE };
  for (const key of Object.keys(RESPONSE_TEMPLATE)) {
    if (fields[key] !== undefined && fields[key] !== null) response[key] = fields[key];
  }
  response.completed_at = response.completed_at || new Date(nowMs ?? Date.now()).toISOString();
  response.error_message = String(response.error_message).slice(0, 500);
  return response;
}

const MAX_BOOKS = 50;

const ID_PATTERN = /^[A-Za-z0-9_.:-]{1,80}$/;

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validateRequest(body, config, nowMs) {
  const errors = [];
  const tz = config.timezone || DEFAULT_TIMEZONE;
  const b = body && typeof body === "object" ? body : {};

  const notificationId = String(b.notification_id ?? "").trim();
  if (!ID_PATTERN.test(notificationId)) errors.push("notification_id is missing or has invalid characters");

  const triggerRaw = String(b.trigger_type ?? "Single").trim().toLowerCase();
  const triggerType = triggerRaw === "bulk" ? "Bulk" : triggerRaw === "single" || triggerRaw === "" ? "Single" : null;
  if (!triggerType) errors.push("trigger_type must be Single or Bulk");

  // Replay protection: a captured request stops working after a few minutes.
  // Dry runs have no side effects, so they are exempt; this lets Bubble's API
  // Connector be initialised with fixed sample values.
  const dryRun = parseYesNo(b.dry_run) === true;
  const requestedAt = Number(String(b.requested_at_ms ?? "").replace(/[^0-9]/g, ""));
  const maxAgeMs = (Number(config.max_request_age_minutes) || 10) * 60 * 1000;
  let stale = false;
  if (!requestedAt) {
    errors.push("requested_at_ms is required");
  } else if (!dryRun && Math.abs(nowMs - requestedAt) > maxAgeMs) {
    stale = true;
    errors.push(`request is older than ${maxAgeMs / 60000} minutes (possible replay)`);
  }

  let asOf = parseCalendarDate(b.as_of_ms ?? b.as_of_date, tz);
  if (asOf === undefined) errors.push("as_of_ms is not a valid date");
  if (!asOf) asOf = isoDateInTimezone(nowMs, tz);

  const simulate = String(b.simulate_failure ?? "").trim().toLowerCase();
  if (!["", "ai", "email"].includes(simulate)) errors.push('simulate_failure must be "", "ai" or "email"');

  const a = b.author && typeof b.author === "object" ? b.author : {};
  const author = {
    author_id: String(a.author_id ?? "").trim(),
    name: String(a.name ?? "").trim(),
    email: String(a.email ?? "").trim(),
    city: String(a.city ?? "").trim(),
  };
  if (!ID_PATTERN.test(author.author_id)) errors.push("author.author_id is missing");
  if (!author.name) errors.push("author.name is missing");
  if (!EMAIL_PATTERN.test(author.email)) errors.push("author.email is not a valid email address");

  let rawBooks = b.books;
  if (typeof rawBooks === "string") {
    try {
      rawBooks = JSON.parse(rawBooks);
    } catch {
      errors.push("books is not valid JSON");
      rawBooks = [];
    }
  }
  if (!Array.isArray(rawBooks)) {
    errors.push("books must be a list");
    rawBooks = [];
  }
  if (rawBooks.length > MAX_BOOKS) errors.push(`too many books (max ${MAX_BOOKS})`);

  const seen = new Set();
  const books = rawBooks.map((raw, i) => normaliseBook(raw || {}, i, tz, errors, seen));

  const ok = errors.length === 0;
  const request = {
    notification_id: notificationId,
    idempotency_key: String(b.idempotency_key ?? "").trim() || notificationId,
    trigger_type: triggerType || "Single",
    triggered_by: String(b.triggered_by ?? "").trim(),
    requested_at_ms: requestedAt || null,
    as_of: asOf,
    simulate_failure: config.allow_failure_simulation ? simulate : "",
    dry_run: dryRun,
    author,
    books,
  };

  return {
    ok,
    errors,
    request,
    http_status: ok ? 200 : 400,
    response: ok
      ? null
      : buildResponse(
          {
            status: "Failed",
            notification_id: notificationId,
            author_id: author.author_id,
            error_code: stale ? "stale_request" : "invalid_request",
            error_message: errors.join("; "),
          },
          nowMs,
        ),
  };
}

function normaliseBook(raw, index, tz, errors, seen) {
  const where = `books[${index}]`;
  const bookId = String(raw.book_id ?? "").trim();
  if (!ID_PATTERN.test(bookId)) errors.push(`${where}.book_id is missing`);
  else if (seen.has(bookId)) errors.push(`${where}.book_id ${bookId} is duplicated`);
  seen.add(bookId);

  const title = String(raw.title ?? "").trim();
  if (!title) errors.push(`${where}.title is missing`);

  const status = String(raw.status ?? "").trim();
  const flag = parseYesNo(raw.is_published);
  const isPublished = flag === undefined ? /published/i.test(status) : flag;

  // Books still in production have no MRP or sales yet, so Bubble sends
  // empty values. Royalty figures are only mandatory once a book is live.
  const num = (field, { optional = false } = {}) => {
    const rawValue = raw[field];
    const empty = rawValue === null || rawValue === undefined || String(rawValue).trim() === "";
    if (empty && (optional || !isPublished)) return optional ? null : 0;
    const v = parseAmount(rawValue);
    if (Number.isNaN(v) || v < 0) {
      errors.push(`${where}.${field} must be a non-negative number`);
      return 0;
    }
    return v;
  };
  const date = (field) => {
    const v = parseCalendarDate(raw[field], tz);
    if (v === undefined) {
      errors.push(`${where}.${field} is not a valid date`);
      return null;
    }
    return v;
  };

  const book = {
    book_id: bookId,
    title,
    isbn: String(raw.isbn ?? "").trim(),
    genre: String(raw.genre ?? "").trim(),
    status,
    is_published: isPublished,
    publication_date: date("publication_date_ms"),
    mrp: num("mrp", { optional: true }),
    royalty_per_copy: num("royalty_per_copy", { optional: true }),
    copies_sold: num("copies_sold"),
    royalty_earned: num("royalty_earned"),
    royalty_paid: num("royalty_paid"),
    royalty_pending: num("royalty_pending"),
    last_payout_date: date("last_payout_date_ms"),
    print_partner: String(raw.print_partner ?? "").trim(),
    available_on: normaliseList(raw.available_on),
  };

  // The dataset's figures always satisfy earned = paid + pending. If Bubble's
  // copy ever drifts, refuse to email an author numbers that don't add up.
  if (Math.abs(book.royalty_earned - (book.royalty_paid + book.royalty_pending)) > 1) {
    errors.push(`${where} (${bookId}) royalty figures do not add up: earned must equal paid + pending`);
  }
  return book;
}

function normaliseList(value) {
  if (Array.isArray(value)) return value.map((v) => String(v).trim()).filter(Boolean);
  return String(value ?? "")
    .split(",")
    .map((v) => v.trim())
    .filter(Boolean);
}

// ---- node entry ----

const config = $('Config').first().json;
return [{ json: { ...validateRequest($('Bubble webhook').first().json.body, config, Date.now()), started_ms: Date.now() } }];

// Generated from n8n/src/*.js by scripts/build-workflows.mjs. Edit the source files, not this node.

const POLICY = {
  minPayoutInr: 1000, // KB: balances below this roll over to the next quarter
  payoutWindowDays: 45, // KB: paid within 45 days of the quarter ending
  overdueAfterDays: 90, // brief: red badge after 90 days without a payout
  financeResponseHours: 48, // KB playbook: overdue royalties escalated with a 48-hour timeline
};

const PRODUCTION_STAGES = [
  "Manuscript Received",
  "Editing",
  "Cover Design",
  "Typesetting",
  "Proofreading",
  "ISBN Assignment",
  "Printing",
  "Distribution Setup",
  "Published & Live",
];

const DAY_MS = 24 * 60 * 60 * 1000;

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function utcDate(iso) {
  return new Date(`${iso}T00:00:00Z`);
}

function isoOf(date) {
  return date.toISOString().slice(0, 10);
}

function addDays(iso, days) {
  return isoOf(new Date(utcDate(iso).getTime() + days * DAY_MS));
}

/** Whole days from `fromIso` to `toIso` (positive when `toIso` is later). */
function daysBetween(fromIso, toIso) {
  return Math.round((utcDate(toIso).getTime() - utcDate(fromIso).getTime()) / DAY_MS);
}

/** "14 Nov 2026" */
function formatLongDate(iso) {
  if (!iso) return "";
  const d = utcDate(iso);
  return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

/** "₹11,970" with Indian digit grouping (₹1,23,456). */
function formatInr(amount) {
  const n = Math.round(Number(amount) || 0);
  return `₹${new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n)}`;
}

function formatCount(n) {
  return new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(Number(n) || 0);
}

function quarterOf(iso) {
  const d = utcDate(iso);
  const year = d.getUTCFullYear();
  const quarter = Math.floor(d.getUTCMonth() / 3) + 1;
  const start = isoOf(new Date(Date.UTC(year, (quarter - 1) * 3, 1)));
  const end = isoOf(new Date(Date.UTC(year, quarter * 3, 0))); // day 0 of next quarter
  return { year, quarter, start, end, label: `Q${quarter} ${year}` };
}

function previousQuarter(q) {
  return quarterOf(addDays(q.start, -1));
}

function payoutCycle(q) {
  const deadline = addDays(q.end, POLICY.payoutWindowDays);
  return {
    label: q.label,
    quarter_start: q.start,
    quarter_end: q.end,
    deadline,
    quarter_end_label: formatLongDate(q.end),
    deadline_label: formatLongDate(deadline),
  };
}

/**
 * The payout an author can expect next, and the most recent one whose window
 * has already closed. Early in a quarter the previous quarter's window is
 * still open, so that is the "upcoming" payout.
 */
function royaltyCalendar(asOfIso) {
  const current = quarterOf(asOfIso);
  const lastClosed = previousQuarter(current);
  const lastClosedDeadline = addDays(lastClosed.end, POLICY.payoutWindowDays);
  const windowOpen = asOfIso <= lastClosedDeadline;
  return {
    as_of: asOfIso,
    current_quarter: current.label,
    upcoming: payoutCycle(windowOpen ? lastClosed : current),
    last_closed: payoutCycle(windowOpen ? previousQuarter(lastClosed) : lastClosed),
  };
}

/**
 * Every answer n8n gives Bubble has the same keys, whatever the outcome, so
 * Bubble's API Connector can be initialised once and every field mapped into
 * the Notification Log. Empty strings / zeros mean "not applicable".
 */
const RESPONSE_TEMPLATE = {
  status: "", // "Success" | "Failed" | "Duplicate"
  notification_id: "",
  author_id: "",
  completed_at: "", // ISO-8601 timestamp of when n8n finished
  email_subject: "",
  email_html: "",
  email_text: "",
  email_delivery: "not_attempted", // "sent" | "disabled" | "failed" | "not_attempted"
  intended_recipient: "",
  delivered_to: "",
  ai_model: "",
  ai_attempts: 0,
  prompt_version: "",
  total_earned: 0,
  total_paid: 0,
  total_pending: 0,
  overdue_books: 0,
  escalated_to_finance: "no",
  duplicate_of: "",
  error_code: "",
  error_message: "",
  n8n_execution_id: "",
  duration_ms: 0,
};

function buildResponse(fields, nowMs) {
  const response = { ...RESPONSE_TEMPLATE };
  for (const key of Object.keys(RESPONSE_TEMPLATE)) {
    if (fields[key] !== undefined && fields[key] !== null) response[key] = fields[key];
  }
  response.completed_at = response.completed_at || new Date(nowMs ?? Date.now()).toISOString();
  response.error_message = String(response.error_message).slice(0, 500);
  return response;
}

const BADGES = {
  in_production: { badge: "grey", label: "In production" },
  no_earnings: { badge: "green", label: "Paid up" },
  paid_up: { badge: "green", label: "Paid up" },
  below_threshold: { badge: "yellow", label: "Pending" },
  pending: { badge: "yellow", label: "Pending" },
  overdue: { badge: "red", label: "Overdue" },
};

function productionStage(status) {
  const name = String(status || "")
    .replace(/^in production\s*[-–:]\s*/i, "")
    .trim();
  const index = PRODUCTION_STAGES.findIndex((s) => s.toLowerCase() === name.toLowerCase());
  if (index === -1) return { current_stage: name || "In production", stage_number: null, of: PRODUCTION_STAGES.length, next_stage: null };
  return {
    current_stage: PRODUCTION_STAGES[index],
    stage_number: index + 1,
    of: PRODUCTION_STAGES.length,
    next_stage: PRODUCTION_STAGES[index + 1] || null,
  };
}

/** Royalty state of one book on a given day. */
function assessBook(book, asOfIso) {
  const daysSinceLastPayout = book.last_payout_date ? daysBetween(book.last_payout_date, asOfIso) : null;
  const daysSincePublication = book.publication_date ? daysBetween(book.publication_date, asOfIso) : null;
  const neverPaid = !book.last_payout_date;
  let state;
  let reason = "";

  if (!book.is_published) {
    state = "in_production";
  } else if (book.royalty_earned <= 0) {
    state = "no_earnings";
  } else if (book.royalty_pending <= 0) {
    state = "paid_up";
  } else if (book.royalty_pending < POLICY.minPayoutInr) {
    state = "below_threshold";
  } else if (!neverPaid && daysSinceLastPayout > POLICY.overdueAfterDays) {
    state = "overdue";
    reason = `last payout was ${daysSinceLastPayout} days ago (more than ${POLICY.overdueAfterDays})`;
  } else if (neverPaid && daysSincePublication !== null && daysSincePublication > POLICY.overdueAfterDays) {
    state = "overdue";
    reason = `no payout has ever been made and the book was published ${daysSincePublication} days ago`;
  } else {
    state = "pending";
  }

  return {
    state,
    ...BADGES[state],
    never_paid: neverPaid && book.is_published && book.royalty_earned > 0,
    days_since_last_payout: daysSinceLastPayout,
    days_since_publication: daysSincePublication,
    overdue_reason: reason,
  };
}

function computeFacts(request) {
  const asOf = request.as_of;
  const calendar = royaltyCalendar(asOf);
  const books = request.books.map((b) => ({ ...b, ...assessBook(b, asOf) }));
  const published = books.filter((b) => b.is_published);
  const inProduction = books.filter((b) => !b.is_published);

  const sum = (list, field) => list.reduce((acc, b) => acc + b[field], 0);
  const totals = {
    books_published: published.length,
    books_in_production: inProduction.length,
    copies_sold: sum(published, "copies_sold"),
    earned: sum(published, "royalty_earned"),
    paid: sum(published, "royalty_paid"),
    pending: sum(published, "royalty_pending"),
  };
  const overdueBooks = books.filter((b) => b.state === "overdue");
  const scheduledBooks = books.filter((b) => b.state === "pending");
  const belowThresholdBooks = books.filter((b) => b.state === "below_threshold");
  const neverPaidBooks = books.filter((b) => b.never_paid && b.royalty_pending > 0);
  const overdueTotal = sum(overdueBooks, "royalty_pending");
  const scheduledTotal = sum(scheduledBooks, "royalty_pending");

  const cases = [];
  if (published.length && totals.pending === 0 && totals.earned > 0) cases.push("all_paid_up");
  if (scheduledBooks.length) cases.push("pending_scheduled");
  if (overdueBooks.length) cases.push("overdue");
  if (neverPaidBooks.length) cases.push("never_paid");
  if (belowThresholdBooks.length) cases.push("below_threshold");
  if (inProduction.length) cases.push("in_production");
  if (!published.length) cases.push("no_published_books");
  if (published.length && totals.earned === 0) cases.push("no_earnings_yet");

  const authorStatus = overdueBooks.length ? "Overdue" : totals.pending > 0 ? "Pending" : "Paid up";

  // What the model is allowed to quote: exactly what factsForPrompt shows it.
  // Anything else is treated as invented.
  const amounts = new Set([POLICY.minPayoutInr, totals.earned, totals.paid, totals.pending, overdueTotal, scheduledTotal]);
  for (const b of books) [b.royalty_per_copy, b.royalty_earned, b.royalty_paid, b.royalty_pending].forEach((v) => amounts.add(v));
  const dates = new Set([asOf, calendar.upcoming.deadline, calendar.upcoming.quarter_end]);
  for (const b of books) [b.publication_date, b.last_payout_date].forEach((d) => d && dates.add(d));

  return {
    as_of: asOf,
    as_of_label: formatLongDate(asOf),
    author: {
      ...request.author,
      first_name: request.author.name.split(/\s+/)[0],
    },
    calendar,
    books,
    totals,
    author_status: authorStatus,
    cases,
    overdue: { count: overdueBooks.length, total: overdueTotal, book_ids: overdueBooks.map((b) => b.book_id) },
    scheduled: { count: scheduledBooks.length, total: scheduledTotal },
    escalation: overdueBooks.length
      ? { team: "finance", respond_within_hours: POLICY.financeResponseHours, book_ids: overdueBooks.map((b) => b.book_id) }
      : null,
    allowed: {
      amounts: [...amounts].filter((v) => Number.isFinite(v)).sort((x, y) => x - y),
      dates: [...dates].filter(Boolean).sort(),
      quarters: [calendar.upcoming.label],
    },
  };
}

/**
 * The view of FACTS the model sees: labels already formatted exactly as they
 * must appear in the email (₹11,970 / 15 Oct 2025), plus plain-English
 * descriptions of each book's position, so the model copies rather than
 * computes.
 */
function factsForPrompt(facts) {
  const { calendar, totals } = facts;
  return {
    as_of: facts.as_of_label,
    author: { first_name: facts.author.first_name, full_name: facts.author.name, city: facts.author.city },
    payout_calendar: {
      policy: `Royalties are calculated quarterly and paid within 45 days of the quarter ending. Minimum payout ${formatInr(POLICY.minPayoutInr)}; smaller balances roll over to the next quarter.`,
      next_payout: {
        quarter: calendar.upcoming.label,
        quarter_ended_or_ends: calendar.upcoming.quarter_end_label,
        paid_by: calendar.upcoming.deadline_label,
      },
    },
    totals: {
      books_published: totals.books_published,
      books_in_production: totals.books_in_production,
      copies_sold: formatCount(totals.copies_sold),
      total_earned: formatInr(totals.earned),
      total_paid: formatInr(totals.paid),
      total_pending: formatInr(totals.pending),
      pending_that_is_overdue: facts.overdue.count ? formatInr(facts.overdue.total) : null,
      pending_scheduled_for_next_payout: facts.scheduled.count ? formatInr(facts.scheduled.total) : null,
    },
    books: facts.books.map((b) =>
      b.is_published
        ? {
            book_id: b.book_id,
            title: b.title,
            status: "Published & Live",
            published_on: formatLongDate(b.publication_date),
            copies_sold: formatCount(b.copies_sold),
            royalty_per_copy: formatInr(b.royalty_per_copy),
            royalty_earned: formatInr(b.royalty_earned),
            royalty_paid: formatInr(b.royalty_paid),
            royalty_pending: formatInr(b.royalty_pending),
            last_payout: b.last_payout_date ? formatLongDate(b.last_payout_date) : "No payout yet",
            payout_position: describePosition(b, calendar),
          }
        : {
            book_id: b.book_id,
            title: b.title,
            status: "In production",
            production: productionStage(b.status),
            payout_position: "Not published yet, so no sales or royalties yet.",
          },
    ),
    cases: facts.cases,
    finance_escalation: facts.escalation
      ? `Our finance team has been alerted about the overdue amount and will update you within ${facts.escalation.respond_within_hours} hours.`
      : null,
  };
}

function describePosition(book, calendar) {
  const pending = formatInr(book.royalty_pending);
  switch (book.state) {
    case "no_earnings":
      return "No royalties earned yet.";
    case "paid_up":
      return "Fully paid: nothing pending.";
    case "below_threshold":
      return `${pending} pending is below the ${formatInr(POLICY.minPayoutInr)} minimum payout, so it rolls over until the balance reaches ${formatInr(POLICY.minPayoutInr)}.`;
    case "overdue":
      return book.never_paid
