function nodeBuildPrimaryRequest(facts, request, config) {
  const model = request.simulate_failure === "ai" ? SIMULATED_FAILURE_MODEL : config.primary_model;
  return { attempt: 1, ...buildGeminiRequest(facts, { model }) };
}

